//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLMeasure.
package musicxml
import("encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing";"github.com/shibukawa/tinygodriver/encoding/xmlro";"github.com/shibukawa/bdf/converter/internal/music")
func TestCodexMusicXMLMeasure(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(245231));notes:=[]string{`<pitch><step>C</step><octave>4</octave></pitch>`,`<pitch><step>D</step><alter>1</alter><octave>5</octave></pitch>`,`<unpitched><display-step>F</display-step><display-octave>4</display-octave></unpitched>`,`<rest/>`,`<rest measure="yes"/>`,`<pitch><step>G</step><octave>3</octave></pitch><accidental>flat</accidental>`,`<pitch><step>E</step><octave>4</octave></pitch><notations><tied type="start"/></notations>`};types:=[]string{"",`<type>quarter</type>`,`<type>eighth</type><dot/>`,`<type>16th</type>`,`<type>weird</type>`,`<type size="cue">quarter</type>`};extras:=[]string{"",`<chord/>`,`<grace slash="yes"/>`,`<cue/>`,`<stem>up</stem>`,`<beam number="1">begin</beam>`,`<voice>3</voice><staff>2</staff>`,`<time-modification><actual-notes>3</actual-notes><normal-notes>2</normal-notes></time-modification>`,`<tie type="stop"/>`};out:=[]any{}
 for i:=0;i<5000;i++ {div:=[]int{1,2,4,24,96,960}[r.Intn(6)];time:=music.TimeSig{Beats:[]int{3,4,6}[r.Intn(3)],BeatType:[]int{4,8}[r.Intn(2)]};src:="<measure>";for j:=0;j<1+r.Intn(15);j++{switch r.Intn(9){case 0:src+=fmt.Sprintf("<backup><duration>%d</duration></backup>",r.Intn(div*3+1));case 1:src+=fmt.Sprintf("<forward><duration>%d</duration></forward>",r.Intn(div*3+1));default:dur:="";if r.Intn(3)!=0{dur=fmt.Sprintf("<duration>%d</duration>",r.Intn(div*3+1))};src+=fmt.Sprintf(`<note dynamics="%d">%s%s%s%s</note>`,r.Intn(130),notes[r.Intn(len(notes))],dur,types[r.Intn(len(types))],extras[r.Intn(len(extras))])}};src+="</measure>";d:=newXMLReader([]byte(src));for{k,e:=d.Next();if e!=nil{t.Fatal(e)};if k==xmlro.StartElement{break}};n,e:=readNode(d);if e!=nil{t.Fatal(e)};reader:=newReader();p:=newPart("P1","");p.div=float64(div);p.time=time;p.transpose=r.Intn(25)-12;st:=&mstate{pm:&music.PartMeasure{},play:&playMeasure{},tuplets:map[int]*tupletState{}};for _,child:=range n.kids{switch child.name{case "note":reader.note(p,st,child);case "forward":st.pos=min(st.pos+max(p.quarters(child.textOf("duration")),0),maxQuarters);st.end=max(st.end,st.pos);case "backup":st.pos=max(st.pos-p.quarters(child.textOf("duration")),0)}};events:=[]any{};for _,ev:=range st.pm.Events{ns:=[]any{};for _,note:=range ev.Notes{key:=-1;if note.SoundingMIDI!=nil{key=*note.SoundingMIDI};ns=append(ns,[]any{note.Pitch.Step,note.Pitch.Alter,note.Pitch.Octave,key,int(note.Accidental),note.TieStart,note.TieStop})};beams:=[]int{};for _,v:=range ev.Beams{beams=append(beams,int(v))};events=append(events,[]any{ev.Offset,ev.Duration,ev.Staff,ev.Voice,int(ev.Type),ev.Dots,ev.Grace,ev.Slash,ev.Cue,ev.Hidden,int(ev.Stem),ev.Rest,ev.MeasureRest,beams,ns})};played:=[]any{};for _,v:=range st.play.notes{played=append(played,[]any{v.offset,v.dur,v.key,v.staff,v.voice,v.grace,v.vel,v.tieStart,v.tieStop})};out=append(out,map[string]any{"input":[]byte(src),"div":div,"beats":time.Beats,"beatType":time.BeatType,"transpose":p.transpose,"want":[]any{st.pos,st.end,p.part.Staves,reader.hasBeams,reader.hasAltered,reader.hasAccidentals,p.unpitched,events,played}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/measure.json"),b,0644);e!=nil{t.Fatal(e)}}
